#!/bin/sh
# Fails if any tracked file looks like a real consumer raw-data export.
#
# Every vendor the workbench reads is covered here. Synthetic fixtures are
# generated with a banner saying what they are, and deliberately never begin
# the way a real export does, so they pass.
set -e

hits=$(git ls-files -z | xargs -0 grep -l -I -E \
  "^# This data file generated by 23andMe|^#AncestryDNA raw data download|^# MyHeritage DNA raw data" \
  2>/dev/null || true)

# FamilyTreeDNA exports carry no comment banner at all: the column names are the
# first line of the file. That is the only thing distinguishing a real one, so a
# tracked file starting that way is treated as real.
ftdna=$(
  git ls-files | while IFS= read -r f; do
    [ -f "$f" ] || continue
    # LC_ALL=C so tr does not object to the bytes in images and parquet files.
    first=$(head -n 1 "$f" 2>/dev/null | LC_ALL=C tr -d '\r' 2>/dev/null)
    if [ "$first" = "RSID,CHROMOSOME,POSITION,RESULT" ]; then printf '%s\n' "$f"; fi
  done
)

hits=$(printf '%s\n%s' "$hits" "$ftdna" | grep -v '^$' || true)

if [ -n "$hits" ]; then
  echo "Refusing: these tracked files look like real raw genotype exports:"
  echo "$hits"
  exit 1
fi
echo "ok: no raw genotype exports tracked"
